<template><button class="figma-button" :class="[`figma-button--${variant}`,`figma-button--${size}`,{disabled}]" :disabled="disabled||loading" type="button" @click="emit('click',$event)"><span v-if="loading">处理中</span><slot v-else>{{ label }}</slot></button></template>
