<style scoped>.figma-button{width:100%;min-height:44px;padding:12px 16px;box-sizing:border-box;border:1px solid transparent;border-radius:20px;font:500 16px/20px "PingFang SC",sans-serif}.figma-button--primary{border-color:#22BBB3;color:#fff;background:#22BBB3}.figma-button--secondary{border-color:#E5E6EB;color:#1D2129;background:#fff}.figma-button--tertiary{border-color:transparent;color:#00AAA6;background:transparent}.figma-button--large{min-height:48px;border-radius:24px}.figma-button--small{min-height:32px;padding:6px 12px;border-radius:16px;font-size:12px}.figma-button.disabled{border-color:#79DDD1;color:#fff;background:#79DDD1;opacity:1}</style>
